function plot_single_controller(result,p)
%PLOT_SINGLE_CONTROLLER Plot one controller result generated by main_single_controller.m.
%
% Exact result fields in the current project:
%   t, x, ref, ep, eth, u, s, mp, alpha, controller, caseNo, metrics
%
% This function is visualization-only and does not alter result or p.

S = config_plot_style();
t = result.t(:);
name = upper(result.controller);

switch name
    case 'SMC'
        cs = S.SMC;
    case 'STSMC'
        cs = S.STSMC;
    case 'ASTSMC'
        cs = S.ASTSMC;
    otherwise
        error('plot_results:UnknownController','Unknown controller: %s',result.controller);
end

% main_single_controller.m does not pass an output folder, therefore these figures are shown
% interactively and are not exported automatically. main.m handles
% the publication exports for all three controllers.

% Trajectory
fig = new_figure(S,[name ' trajectory']);
ax = axes(fig); hold(ax,'on');
plot(ax,result.ref(:,1),result.ref(:,2),'k:','LineWidth',S.RefLineWidth);
plot(ax,result.x(:,1),result.x(:,2),'Color',cs.Color,'LineStyle',cs.LineStyle,'LineWidth',S.LineWidth);
xlabel(ax,'x [m]','Interpreter','tex'); ylabel(ax,'y [m]','Interpreter','tex');
axis(ax,'equal'); legend(ax,{'Reference',name},'Location','best','Interpreter','none');
finish_axes(ax,S);

% Position error
fig = new_figure(S,[name ' position error']);
ax = axes(fig);
plot(ax,t,result.ep,'Color',cs.Color,'LineStyle',cs.LineStyle,'LineWidth',S.LineWidth);
xlabel(ax,'Time [s]','Interpreter','tex'); ylabel(ax,'Position error [m]','Interpreter','tex');
finish_axes(ax,S);

% Sliding variables
fig = new_figure(S,[name ' sliding variables']);
tl = tiledlayout(fig,2,1,'TileSpacing','compact','Padding','compact'); %#ok<NASGU>
ax1 = nexttile; plot(ax1,t,result.s(:,1),'Color',cs.Color,'LineStyle',cs.LineStyle,'LineWidth',S.LineWidth);
ylabel(ax1,'s_v','Interpreter','tex'); finish_axes(ax1,S);
ax2 = nexttile; plot(ax2,t,result.s(:,2),'Color',cs.Color,'LineStyle',cs.LineStyle,'LineWidth',S.LineWidth);
xlabel(ax2,'Time [s]','Interpreter','tex'); ylabel(ax2,'s_\omega','Interpreter','tex'); finish_axes(ax2,S);

% Generalized inputs
fig = new_figure(S,[name ' control inputs']);
tl = tiledlayout(fig,2,1,'TileSpacing','compact','Padding','compact'); %#ok<NASGU>
ax1 = nexttile; plot(ax1,t,result.u(:,1),'Color',cs.Color,'LineStyle',cs.LineStyle,'LineWidth',S.LineWidth);
ylabel(ax1,'u_v [N]','Interpreter','tex'); finish_axes(ax1,S);
ax2 = nexttile; plot(ax2,t,result.u(:,2),'Color',cs.Color,'LineStyle',cs.LineStyle,'LineWidth',S.LineWidth);
xlabel(ax2,'Time [s]','Interpreter','tex'); ylabel(ax2,'u_\omega [N\cdot m]','Interpreter','tex'); finish_axes(ax2,S);

% ASTSMC gains
if strcmpi(name,'ASTSMC') && any(isfinite(result.alpha(:)))
    fig = new_figure(S,'ASTSMC adaptive gains');
    ax = axes(fig); hold(ax,'on');
    plot(ax,t,result.alpha(:,1),'Color',S.SMC.Color,'LineStyle','-','LineWidth',S.LineWidth);
    plot(ax,t,result.alpha(:,2),'Color',S.STSMC.Color,'LineStyle','--','LineWidth',S.LineWidth);
    xlabel(ax,'Time [s]','Interpreter','tex'); ylabel(ax,'Adaptive gain','Interpreter','tex');
    legend(ax,{'\alpha_v','\alpha_\omega'},'Location','best','Interpreter','tex');
    finish_axes(ax,S);
end

end

function fig = new_figure(S,figName)
fig = figure('Name',figName,'NumberTitle','off','Color','w', ...
    'Units','centimeters','Position',[2 2 S.FigureWidthCm S.FigureHeightCm], ...
    'PaperUnits','centimeters','PaperPosition',[0 0 S.FigureWidthCm S.FigureHeightCm], ...
    'PaperSize',[S.FigureWidthCm S.FigureHeightCm]);
end

function finish_axes(ax,S)
set(ax,'FontName',S.FontName,'FontSize',S.FontSize,'LineWidth',0.8, ...
    'Box','on','TickLabelInterpreter','tex');
grid(ax,'on'); ax.GridAlpha=S.GridAlpha; ax.MinorGridAlpha=S.MinorGridAlpha;
if ~isempty(ax.XLabel), set(ax.XLabel,'FontName',S.FontName,'FontSize',S.FontSize,'FontWeight','normal'); end
if ~isempty(ax.YLabel), set(ax.YLabel,'FontName',S.FontName,'FontSize',S.FontSize,'FontWeight','normal'); end
lgd = legend(ax);
if ~isempty(lgd) && isvalid(lgd), set(lgd,'FontName',S.FontName,'FontSize',S.FontSize); end
end
